/* Visual refinement of the approved 20-page wireframe. Still entirely offline. */
function hfHead(t,d=''){return `<h1>${t}</h1>${d?`<p class="muted">${d}</p>`:''}<div class="space"></div>`}
function hfTile(ic,c=''){return `<div class="avatar ${c}">${icon(ic)}</div>`}
function hfKv(k,v){return `<div class="kv"><span>${k}</span><b>${v}</b></div>`}
function hfSection(t,l='',g=''){return `<div class="section"><h2>${t}</h2>${g?`<button class="textbtn" data-go="${g}">${l} ${icon('chev')}</button>`:l}</div>`}
function home(){return `<div class="row between"><span class="hf-eyebrow">上午好，林悦</span><button class="textbtn" data-go="usage">用量 ${icon('chev')}</button></div><h1 class="hf-home-title">把想法，变成<br><em>下一步。</em><span class="hf-spark">${icon('spark')}</span></h1><div class="card hf-intent"><label class="sr-only" for="home-prompt">想完成的任务</label><textarea id="home-prompt" class="textarea" placeholder="整理客户反馈，生成一份行动清单…"></textarea><div class="row between"><span class="row tiny">${icon('shield')}在当前空间安全执行</span><button class="btn primary" data-act="home-start" aria-label="选择助手并继续">${icon('send')}</button></div></div><div class="hf-chips"><button data-act="home-preset" data-text="整理本周项目进展，生成团队周报。">帮我写周报</button><button data-act="home-preset" data-text="梳理客户反馈，提炼优先改进方向。">梳理产品需求</button></div>${hfSection('你的 AI 助手','查看全部','agents')}<div class="grid2"><button class="card choose hf-agent-mini" data-go="chat">${hfTile('knowledge')}<h3>知识问答助手</h3><span class="tiny">有据可循，放心提问</span></button><button class="card choose hf-agent-mini" data-go="agent">${hfTile('tasks','amber')}<h3>周报整理助手</h3><span class="tiny">整理进展，留住重点</span></button></div>${hfSection('需要你关注',tag(state.approval==='pending'?'1 项待处理':'已处理',state.approval==='pending'?'wait':'done'))}<button class="card taskcard hf-attention" data-go="approval"><div class="row">${hfTile('shield','amber')}<div class="grow"><h3>${state.approval==='pending'?'发送周报前，确认一下':'本次审批已处理'}</h3><div class="tiny">${state.approval==='pending'?'草稿已准备好，最后一步由你决定。':'查看当前任务与处理结果。'}</div></div>${icon('chev')}</div></button>${hfSection('最近会话','继续提问','chat')}<div class="card flat">${row('产品上线需要准备哪些资料？','知识问答助手 · 今天 09:12','chat','knowledge')}</div>`}
function login(){return `<div class="hf-loginbrand"><div class="brandmark">W</div>WeKnora</div><h1>随时开始，<br>把工作交给 AI。</h1><p class="muted">你的知识、助手与任务，<br>在同一个工作空间里，随身同行。</p><div class="hf-loginart"><div class="hf-art-chip">${icon('knowledge')}知识有来源，答案更可靠</div><br><div class="hf-art-chip second">${icon('check')}任务在继续，你不必一直等待</div></div><div class="checkline"><input id="consent" type="checkbox"/><div><label for="consent">我已阅读并同意 </label><button class="textbtn" data-act="privacy">隐私政策</button> 与 <button class="textbtn" data-act="terms">服务协议</button></div></div>${btn(state.bindMode?'验证微信身份并绑定':'微信快捷登录','','primary full','login-wx')}<div id="login-error" class="errorline" role="alert"></div><div class="space"></div><details class="card"><summary style="font-size:13px;min-height:24px;cursor:pointer">${state.bindMode?'绑定已有平台账号':'使用已有平台账号'}</summary>${label('邮箱 / 账号','account')}<input class="input" id="account" placeholder="平台账号" autocomplete="username"/>${label('密码','password')}<input class="input" id="password" type="password" placeholder="密码（仅本地演示）" autocomplete="current-password"/><div class="space"></div>${btn(state.bindMode?'验证原账号并绑定':'登录平台账号','','full','login-account')}</details><button class="textbtn" style="display:flex;margin:auto" data-act="bind">${state.bindMode?'返回登录':'已有账号？绑定后继续使用'}</button><p class="tiny" style="text-align:center;margin-top:10px">离线交互原型，不发送账号、密码或微信凭证。</p>`}
function workspace(){return `${hfHead('选择工作空间','个人想法与团队工作，清晰分开。')}${[['我的个人空间','只属于你的资料与任务','me','所有者'],['青禾产品团队','团队知识与日常协作','users','成员']].map(([n,d,i,r])=>`<button class="card choose full ${state.selection===n?'selected':''}" data-act="select-space" data-space="${n}" style="width:100%;padding:19px;margin-bottom:14px"><div class="row">${hfTile(i)}<div class="grow"><h3>${n}</h3><div class="tiny">${d}</div></div><span class="check">${state.selection===n?'✓':''}</span></div><div class="tiny" style="margin:14px 0 0 54px">${r} · ${n.startsWith('我的')?'个人专属':'已加入团队'}</div></button>`).join('')}<div class="notice">切换后，会话、任务、资料与额度将切换为该空间的数据。</div>${btn('进入工作空间','','primary full','enter-space')}<div class="row between"><button class="textbtn" data-go="invitations">查看邀请</button><button class="textbtn" data-act="create-space">创建新空间 ${icon('plus')}</button></div>`}
function agents(){return `${hfHead('找到合适的助手','把重复的工作，交给擅长它的 AI。')}<div class="searchbox">${icon('search')}<input id="agent-search" class="input" placeholder="搜索助手或想完成的事" aria-label="搜索助手"/></div><div class="segments">${[['all','全部助手'],['team','团队助手'],['mine','我的常用']].map(([k,v])=>`<button data-act="agent-filter" data-filter="${k}" class="${state.agentFilter===k?'active':''}">${v}</button>`).join('')}</div><div id="agent-cards">${agentCards()}</div><div class="notice">这里使用已配置的助手。模型、MCP 与高级编排请在 Web 管理端配置。</div>`}
function agentCards(q=''){return [{name:'知识问答助手',desc:'从团队知识中找到可靠答案，让结论有据可循。',go:'chat',kind:'team',ic:'knowledge',color:'',tags:['知识问答','引用溯源']},{name:'周报整理助手',desc:'梳理进展、提炼重点，生成可以直接审阅的周报。',go:'agent',kind:'team',ic:'tasks',color:'amber',tags:['长任务','需要确认']},{name:'文档写作助手',desc:'把零散想法组织成清晰文档，减少从空白开始的时间。',go:'agent',kind:'mine',ic:'file',color:'blue',tags:['写作','个人常用']}].filter(a=>(state.agentFilter==='all'||state.agentFilter===a.kind)&&(!q||a.name.includes(q)||a.desc.includes(q))).map(a=>`<button class="card taskcard" data-go="${a.go}" data-agent="${a.name}" style="padding:18px"><div class="row">${hfTile(a.ic,a.color)}<div class="grow"><h3>${a.name}</h3><div class="tiny">${a.desc}</div></div>${icon('chev')}</div><div class="tags" style="margin:14px 0 0 54px">${a.tags.map(t=>tag(t)).join('')}</div></button>`).join('')||'<div class="card empty"><h3>没有找到相关助手</h3><p>换个关键词，或查看团队开放的助手。</p></div>'}
function agent(){return `<div class="hf-hero"><div class="row between">${hfTile('tasks','large amber')}${tag('平台托管','done')}</div><h1>周报整理助手</h1><p>把零散进展整理成清晰周报。涉及外部发送时，再单独向你确认。</p><div class="tags">${tag('资料整理')}${tag('生成产物')}${tag('敏感操作需确认','wait')}</div></div><div class="hf-section-number">01 / 告诉助手你想完成什么</div>${label('任务描述','task-input')}<textarea class="textarea" id="task-input" style="min-height:130px">${esc(state.taskText)}</textarea><p class="tiny">越具体，越容易得到你需要的结果。</p><div class="hf-section-number">02 / 确认执行范围</div><div class="card">${hfKv('工作空间',state.tenant)}${hfKv('运行环境','平台托管 · 无需配置')}${hfKv('资料范围','助手已获授权的资源')}</div>${label('本次预算上限（示例单位）','budget')}<input id="budget" class="input" type="number" min="1" value="200" aria-label="本次预算上限"/><p class="tiny">上限不是实际扣费，实际用量以服务端结算为准。</p><div class="notice">本入口提交文字任务。临时文件请使用对话附件，不会自动加入知识库。</div>${btn('确认并发起任务','','primary full','task-start')}`}
function taskCard(n,status,summary=''){return `<article class="card"><div class="row between"><div class="row">${hfTile(n.includes('客户')?'spark':'tasks',status==='waiting_user'?'amber':'')}<span class="tiny">${n.includes('客户')?'需求洞察助手':'周报整理助手'}</span></div>${statusInfo(status)}</div><h3 class="hf-task-title">${n}</h3><p class="tiny">${summary||'正在按你的要求继续执行。'}</p><div class="row between hf-task-footer"><span class="tiny">今天 09:28 · 本人创建</span>${status==='waiting_user'?btn('去确认','approval','small subtle'):btn(status==='succeeded'?'查看产物':'查看进度',status==='succeeded'?'artifact':'execution','small')}</div></article>`}
function tasks(){return `<div class="row between"><div><h1>我的任务</h1><div class="tiny">${state.tenant} · 仅显示本人任务</div></div><button class="iconbtn" data-go="agents" aria-label="创建新任务">${icon('plus')}</button></div><div class="hf-metrics"><div><b>${state.status==='running'?2:1}</b><p>正在执行</p></div><div><b>${state.status==='waiting_user'?1:0}</b><p>需要确认</p></div><div><b>${state.status==='succeeded'?2:1}</b><p>已完成</p></div></div><div class="segments">${[['all','全部'],['running','运行中'],['waiting_user','待确认'],['succeeded','已完成']].map(([k,v])=>`<button data-act="task-filter" data-filter="${k}" class="${state.taskFilter===k?'active':''}">${v}</button>`).join('')}</div>${filteredTasks()}<div class="notice">退出小程序不会取消后台任务。回来后，会同步同一任务的进度。</div>`}
function execution(){let waiting=state.status==='waiting_user',done=state.status==='succeeded',canceled=state.status==='canceled';return `<div class="card hf-dark"><div class="row between">${statusInfo(state.status)}<span class="tiny">周报整理助手</span></div><h1 style="font-size:25px;margin-top:20px">${waiting?'最后一步，等你确认':done?'任务已完成':canceled?'任务已取消':'助手正在继续执行'}</h1><p class="muted">${esc(state.taskText)}</p><div class="row tiny" style="margin-top:15px">${icon('wifi')}${state.network?'已同步最新状态':'连接已断开 · 任务仍在后台'}</div><p class="tiny" style="font-family:var(--font-mono);margin-bottom:0">run_demo_001 · 示例任务</p></div>${!state.network?'<div class="notice warn">当前内容来自最近一次快照。恢复连接只会继续读取同一任务。</div>':''}${hfSection('执行过程')}<div class="card"><div class="timeline"><div class="step"><strong>读取项目资料</strong><p>已读取当前空间中有权访问的资料。<br>09:28</p></div><div class="step"><strong>整理周报草稿</strong><p>已归纳本周进展、风险与下周计划。<br>09:29</p></div><div class="step active"><strong>${done?'产物已保存':canceled?'后续操作已停止':'发送周报到项目群'}</strong><p>${waiting?'这会向群成员发送内容，需要你确认。':done?'草稿与结果可在产物页查看。':canceled?'取消不撤销已完成的外部动作。':'正在按照确认后的范围继续执行。'}</p></div></div></div>${waiting?`<div class="card hf-attention"><h3>对外发送前，需要确认</h3><p class="tiny">目标：青禾产品团队 · 项目协作群</p>${btn('审阅并确认','approval','primary full')}</div>`:''}${done?`<div class="card">${row('本周项目周报.md','已生成 · 可安全预览与下载','artifact','file')}</div>`:''}<div class="card">${hfKv('任务状态',statusInfo(state.status))}${hfKv('结算状态',done?'正在核对用量（演示）':'尚未结算')}${hfKv('连接状态',state.network?'已连接':'已断开')}</div><div class="grid2">${btn('追加指令','','','steer')}${btn('取消任务','','danger','cancel')}</div><button class="democtl" data-act="${state.network?'disconnect':'reconnect'}">演示：${state.network?'断开连接，观察任务状态':'恢复连接，不重新创建任务'}</button><button class="democtl" data-act="complete">演示：任务完成，查看产物</button>`}
function approval(){return `<div style="margin:10px 0 22px">${hfTile('shield','large amber')}<h1 style="font-size:26px;margin-top:16px">这一步，<br>需要你确认。</h1><p class="muted">先核对内容与接收对象，只授权本次操作。</p></div>${state.approval!=='pending'?`<div class="notice warn">${state.approval==='conflict'?'此操作已在其他设备处理，当前版本不可再次提交。':state.approval==='approved'?'你已同意本次操作，后续状态请查看任务。':'你已拒绝本次操作，助手不会凭本次审批继续发送。'}</div>`:''}<div class="card"><div class="row between"><h3>发送周报到项目群</h3>${tag(state.approval==='pending'?'待确认':'已处理',state.approval==='pending'?'wait':'gray')}</div><hr class="divider"/>${hfKv('来自任务','整理本周项目进展')}${hfKv('工作空间',state.tenant)}${hfKv('发送目标','项目协作群')}${hfKv('授权范围','仅本次发送，不永久放行')}</div>${hfSection('将发送的内容')}<div class="card"><div class="row"><span class="tiny">${icon('file')}</span><h3>本周项目周报 · 摘要</h3></div><div class="hf-focus" style="margin-top:12px">本周完成产品资料整理与客户反馈归纳；下周推进上线清单补全、关键需求确认和负责人分配。</div><details class="space-sm"><summary class="textbtn">审阅完整示例内容</summary><p class="muted">本周完成：资料整理与反馈归纳。<br>下周计划：补齐验收清单并明确责任人。<br>需要关注：未确认数据不作为最终结论。</p></details><div class="space"></div></div><div class="notice warn">发送后，群成员能够看到这些内容。预算增加不代表已同意对外发送。</div>${label('拒绝理由（选填）','reason')}<textarea id="reason" class="textarea" style="min-height:75px" placeholder="例如：先删除尚未确认的数据。"></textarea><button class="democtl" data-act="approval-conflict">演示：模拟此操作已在其他设备处理</button>`}
function artifact(){return `<div class="hf-file-cover"><div class="hf-paper">${icon('file')}MD</div><h2>本周项目周报</h2><div class="tiny">Markdown · 2.4 KB（示例）· 周报整理助手</div></div><div class="notice">安全文本预览，不会执行生成的 HTML 或脚本。</div><div class="card hf-paperbody"><div class="hf-eyebrow">WEEKLY REPORT / 示例产物</div><hr class="divider"/><h2>本周项目周报</h2><p>青禾产品团队 · 2026 年 9 月第 3 周</p><h3>01 / 本周完成</h3><p>整理产品上线资料，归纳客户反馈，并形成可追踪的改进清单。</p><h3>02 / 需要关注</h3><p>部分需求仍需确认负责人；上线验收清单需要补全异常路径。</p><h3>03 / 下周计划</h3><p>推进需求确认、完善验收标准，完成第一轮联调评审。</p></div><div class="grid2">${btn('返回任务','execution')}${btn('下载示例文件','','primary','download')}</div>`}
function knowledge(){return `${hfHead('把知识，用起来。','在资料里找到答案，在答案里找到依据。')}<div class="searchbox">${icon('search')}<input id="knowledge-search" class="input" placeholder="搜索知识库或资料" aria-label="搜索知识库"/></div><div class="segments">${[['all','全部'],['mine','我的'],['space','空间'],['shared','共享']].map(([k,v])=>`<button data-act="kb-filter" data-filter="${k}" class="${(state.kbFilter||'all')===k?'active':''}">${v}</button>`).join('')}</div><div id="hf-kb-cards">${hfKnowledgeCards()}</div>${hfSection('最近文档','添加知识','upload')}<div class="card flat">${row('产品上线检查清单','PDF · 今天更新','document','file')}${row('客户反馈整理','文档 · 正在解析','kb','file')}</div>`}
function hfKnowledgeCards(q=''){return [{name:'产品与业务资料',desc:'产品说明、需求文档与上线清单',type:'space',num:12},{name:'团队流程文档',desc:'让日常协作有章可循',type:'shared',num:8},{name:'我的资料',desc:'收藏灵感，积累自己的知识',type:'mine',num:3}].filter(k=>(!state.kbFilter||state.kbFilter==='all'||state.kbFilter===k.type)&&(!q||k.name.includes(q)||k.desc.includes(q))).map(k=>`<button class="card taskcard" data-go="kb" style="padding:18px"><div class="row">${hfTile(k.type==='shared'?'users':'knowledge',k.type==='shared'?'blue':'')}<div class="grow"><h3>${k.name}</h3><div class="tiny">${k.desc}</div></div>${icon('chev')}</div><div class="row between" style="margin-top:16px"><span class="tiny">${k.num} 份文档 · 今天更新</span>${tag(k.type==='shared'?'共享只读':'可问答 · 可导入',k.type==='shared'?'running':'done')}</div></button>`).join('')||'<div class="card empty"><h3>没有找到知识库</h3><p>换个关键词或筛选条件试试。</p></div>'}
function kb(){return `<div class="space"></div>${hfTile('knowledge','large')}<h1 style="font-size:26px;margin-top:18px">产品与业务资料</h1><p class="muted">产品说明、需求文档与上线清单。<br>仅使用你有权访问的内容。</p><div class="tags">${tag('12 份文档')}${tag('可导入','done')}</div><div class="grid2" style="margin-top:20px">${btn('基于此库提问','chat','primary')}${btn('导入资料','upload')}</div>${hfSection('全部文档','刷新状态','kb')}<div class="card flat">${row('产品上线检查清单','PDF · 今天09:10 · 已就绪','document','file')}${row('客户反馈整理','DOCX · 上传完成，解析中','document','clock')}${row('产品需求说明','PDF · 昨天17:20 · 已就绪','document','file')}${row('历史评审附件','PDF · 解析失败，请检查原文件','document','file')}${state.uploadStage==='parsing'?row('新导入资料','刚刚导入 · 解析中','upload','clock'):''}</div><div class="notice">上传完成后仍需解析。只有就绪的文档才能参与检索。</div>`}
function documentPage(){return `<div class="hf-paper" style="width:47px;height:60px;margin:10px 0 22px;box-shadow:3px 3px 0 #D1DEC8">${icon('file')}PDF</div><h1 style="font-size:25px">产品上线检查清单</h1><div class="hf-titlemeta">产品与业务资料 · 今天 09:10 更新</div><div class="tags">${tag('已就绪','done')}${tag('授权访问')}</div><div class="space"></div><div class="card"><div class="hf-eyebrow">引用片段 / [1]</div><div class="quote">产品上线前，需要完成产品说明、验收清单和运营材料的准备。验收清单应覆盖关键业务路径、权限控制与异常场景。</div><p class="tiny">演示文档中的来源片段。没有真实位置数据时，不显示推测页码。</p></div>${hfSection('原文节选')}<div class="card hf-paperbody"><h2>上线准备与团队协作</h2><p>发布前，由对应负责人逐项确认准备状态。涉及对外发布的内容，需要独立审阅。</p><h3>一、产品说明</h3><p>明确目标用户、主要能力、操作流程与使用边界。</p><h3>二、验收清单</h3><p>记录主流程、异常处理、权限范围与负责人，保留验收依据。</p><h3>三、运营材料</h3><p>提供帮助文档、常见问题和用户反馈入口。</p></div><div class="grid2">${btn('下载示例文档','','','download')}${btn('基于文档提问','chat','primary')}</div>`}
function me(){return `<div class="hf-profile"><div class="avatar large">悦</div><div class="grow"><h1>林悦</h1><div class="tiny">平台账号 · 微信已绑定（示例）</div></div></div><button class="card taskcard" data-go="workspace"><div class="row">${hfTile('users')}<div class="grow"><h3>${state.tenant}</h3><div class="tiny">${state.role} · 切换工作空间</div></div>${icon('chev')}</div></button><div class="card hf-dark"><div class="row between"><span class="tiny">用量与权益</span>${tag('团队协作版')}</div><div class="num" style="margin:16px 0 10px">8,640 <span class="tiny" style="font-weight:400">积分 · 示例</span></div><hr class="divider"/><div class="statgrid"><div><span class="tiny">已预占</span><strong>160</strong></div><div><span class="tiny">退款冻结</span><strong>0</strong></div><div><span class="tiny">统计时点</span><strong>09:41</strong></div></div><button class="textbtn" data-go="usage">查看用量明细 ${icon('chev')}</button></div><div class="card flat">${row('套餐与用量','查看额度、明细与可购买方案','usage','wallet')}${row('我的订单','付款与权益发放分别追踪','order','tasks')}${row('空间邀请',state.invitation==='pending'?'1 项待处理邀请（示例）':'暂无待处理邀请','invitations','users')}<button class="listrow" data-act="notify">${icon('bell')}<div class="grow"><h3>任务通知</h3><span class="tiny">按需授权，不默认打扰</span></div>${icon('chev')}</button></div><div class="card flat"><button class="listrow" data-act="privacy">${icon('shield')}<div class="grow"><h3>隐私与服务说明</h3><span class="tiny">了解数据使用与保护方式</span></div>${icon('chev')}</button><button class="listrow" data-act="logout">${icon('me')}<h3>退出登录</h3>${icon('chev')}</button></div><p class="tiny" style="text-align:center">WeKnora · 让每一份知识都能变成行动<br>离线交互原型 · 所有数据均为示例</p>`}
function usage(){return `${hfHead('用量与套餐','看得清额度，用得更安心。')}<div class="card hf-dark"><div class="row between"><span class="tiny">当前可用额度</span>${tag('团队协作版')}</div><div class="num" style="margin:15px 0 6px">8,640 <span class="tiny" style="font-weight:400">积分 · 示例</span></div><p class="tiny">当前空间可用额度，以服务端统计为准。</p><hr class="divider"/><div class="statgrid"><div><span class="tiny">已预占</span><strong>160</strong></div><div><span class="tiny">退款冻结</span><strong>0</strong></div><div><span class="tiny">统计时点</span><strong>09:41</strong></div></div></div><div class="card"><div class="row between"><h3>最近 7 天</h3><span class="tiny">用量趋势 · 示例</span></div><div class="hf-bars" role="img" aria-label="虚构示例7天相对用量，非真实账务数据">${[24,50,39,71,45,61,83].map((v,i)=>`<div class="hf-barcol"><i style="height:${v*.7}px"></i><span>${i===6?'今天':String(i+11)+'日'}</span></div>`).join('')}</div></div>${hfSection('适合团队的方案')}<div class="card hf-plan" style="border-color:#B0CCB0;background:#FBFDF8"><div class="row between"><h2>团队协作包</h2>${tag('30天权益','done')}</div><p class="tiny">为日常知识问答与任务协作补充额度。</p><div class="hf-price">¥99<span class="tiny">.00 / 次 · 示例报价</span></div><div class="hf-plist">✓ 增加 10,000 积分（示例）<br>✓ 当前空间内按授权使用<br>✓ 单次购买，不自动续费</div>${btn('查看报价','checkout','primary full')}</div><div class="notice warn">商品、价格与购买资格以服务端为准。通道未核验时不开放购买。</div>`}
function checkout(){return `${hfHead('确认订单','先确认商品与空间，再继续付款。')}<div class="hf-hero">${hfTile('wallet')}<h1 style="font-size:23px">团队协作包</h1><p>30 天权益 · 一次购买，不自动续费</p><div class="tags">${tag('10,000 积分（示例）')}${tag('空间内共享额度')}</div></div><div class="card">${hfKv('开通空间',state.tenant)}${hfKv('计费方式','按次购买')}${hfKv('报价有效期',state.quoteExpired?'报价已过期':'09:56前有效（演示）')}${hfKv('商品金额','¥99.00')}${hfKv('优惠','¥0.00')}<hr class="divider"/><div class="row between"><span>应付合计</span><span class="hf-price">¥99.00</span></div></div><div class="notice ${state.purchaseEnabled&&!state.quoteExpired?'':'warn'}">${state.quoteExpired?'报价已过期，请重新取得服务端报价。':state.purchaseEnabled?'已开启获准通道的本地模拟。此原型不打开收银台，不收款。':'当前支付通道尚未核验，暂不可购买。不会跳转外部链接绕过限制。'}</div><button class="btn primary full" data-act="pay" ${state.purchaseEnabled&&!state.quoteExpired?'':'disabled'}>${state.quoteExpired?'请刷新报价':state.purchaseEnabled?'确认并模拟支付':'暂不可购买'}</button><button class="democtl" data-act="purchase-toggle">演示开关：${state.purchaseEnabled?'恢复通道待核验':'模拟已开通且有购买权限'}</button><button class="democtl" data-act="quote-toggle">演示：${state.quoteExpired?'重新取得示例报价':'模拟报价过期'}</button><p class="tiny">支付界面返回，不代表已付款或已发放权益。后续查询原订单，不重复购买。</p>`}
function order(){let paid=state.orderPayment==='paid',done=state.orderFulfillment==='fulfilled';return `<div class="hf-orderhead">${hfTile(done?'check':'clock',done?'large':'large amber')}<h1>${done?'权益已开通':paid?'已付款，权益处理中':'付款结果待确认'}</h1><p class="muted">${done?'服务端已确认付款并完成权益发放。':paid?'不用重复付款，正在确认权益发放结果。':'请查询这笔订单，不要重复创建新订单。'}</p></div><div class="card"><div class="hf-check-step">${hfTile(paid?'check':'clock',paid?'':'amber')}<div class="grow"><h3>付款状态</h3><span class="tiny">${paid?'已付款 · 服务端已确认':'待确认 · 客户端操作不等于付款'}</span></div>${tag(paid?'已确认':'待确认',paid?'done':'wait')}</div><div class="hf-check-step">${hfTile(done?'check':'wallet',done?'':'blue')}<div class="grow"><h3>权益发放</h3><span class="tiny">${done?'已发放 · 可返回工作台使用':'尚未完成 · 以服务端履约为准'}</span></div>${tag(done?'已开通':paid?'处理中':'待付款',done?'done':'running')}</div></div><div class="card">${hfKv('商品','团队协作包')}${hfKv('金额','¥99.00（示例）')}${hfKv('所属空间',state.tenant)}${hfKv('订单编号','order_demo_001')}${hfKv('创建时间','2026-09-17 09:41')}</div><div class="grid2">${btn('刷新原订单','','','order-refresh')}${btn('查看用量','usage','primary')}</div><button class="democtl" data-act="order-paid">演示：服务端确认付款</button><button class="democtl" data-act="order-fulfilled" ${!paid?'disabled':''}>演示：服务端完成履约</button>`}
function invitations(){return `${hfHead('空间邀请','加入协作前，先确认邀请与权限。')}<div class="card"><div class="row between">${hfTile('users','large')}${tag(state.invitation==='pending'?'待你处理':state.invitation==='accepted'?'已接受':'已拒绝',state.invitation==='pending'?'wait':'done')}</div><h1 style="font-size:22px;margin-top:20px">青禾产品团队</h1><p class="muted">陈宁邀请你加入工作空间，一起整理用户需求与产品资料。</p><hr class="divider"/>${hfKv('邀请角色','成员')}${hfKv('邀请者','陈宁（示例账号）')}${hfKv('有效期','9月20日18:00前（示例）')}<div class="space"></div><div class="notice">加入后仅获得被授权资源的访问权限，不自动拥有他人的私有任务。</div>${state.invitation==='pending'?`<div class="grid2">${btn('拒绝邀请','','','invite-decline')}${btn('接受邀请','','primary','invite-accept')}</div>`:btn('选择工作空间','workspace','primary full')}</div><p class="tiny">邀请链接只用于定位与服务端校验。匿名打开时仍需先登录。</p>`}
function hfStatus(s){const t={queued:['排队中','running'],running:['运行中','running'],waiting_user:['待你确认','wait'],reconciling:['正在核对','running'],succeeded:['已完成','done'],failed:['执行失败','gray'],canceled:['已取消','gray']}[s]||['状态未知','gray'];return tag(t[0],t[1])}
function filteredTasks(){let items=[['整理本周项目进展',state.status,state.status==='waiting_user'?'周报草稿已完成，发送前需要你确认。':state.status==='succeeded'?'周报已生成，产物可供查看。':'正在按照你的要求继续执行。'],['整理客户反馈要点','running','正在分析已授权资料中的核心问题。'],['产品资料摘要','succeeded','已生成摘要，包含可追溯的资料来源。']];return items.filter(x=>state.taskFilter==='all'||x[1]===state.taskFilter).map(x=>taskCard(...x)).join('')||'<div class="card empty">'+icon('tasks')+'<h3>这里暂时没有任务</h3><p>换个筛选条件，或发起新的任务。</p></div>'}
function upload(){let selected=state.uploadSelected,parsing=state.uploadStage==='parsing',ready=state.uploadStage==='ready';return `${hfHead('添加知识','确认目标后，再将资料加入知识库。')}<div class="card"><div class="row">${hfTile('knowledge')}<div class="grow"><div class="tiny">导入到</div><h3>产品与业务资料</h3></div>${tag('可写入','done')}</div></div><div class="segments"><button data-act="upload-mode" data-value="file" class="${state.uploadMode==='file'?'active':''}">文件导入</button><button data-act="upload-mode" data-value="url" class="${state.uploadMode==='url'?'active':''}">网页链接</button></div>${state.uploadMode==='file'?`<button class="card choose full" data-act="choose-file" style="width:100%;text-align:center;padding:27px 15px;border:1.5px dashed #A6BFA9;background:#F9FCF7">${hfTile(selected?'check':'upload','large')}<h3 style="margin-top:17px">${selected?'产品需求说明.pdf':'选择要加入的文件'}</h3><p class="tiny">${selected?'已选择虚构示例文件 · 240 KB':'点击选择示例文件，不会上传本地内容。'}</p><span class="tag">${selected?'重新选择示例文件':'选择示例文件'}</span></button>`:`${label('网页链接','import-url')}<input id="import-url" class="input" type="url" placeholder="https://…"/><p class="tiny">仅导入你有权使用的内容；服务端最终校验地址与资源。</p>`}<div class="notice">加入知识库后，资料可被该库的授权用户检索。临时聊天附件不会自动保存到这里。</div>${parsing||ready?`<div class="card"><div class="row between"><h3>${ready?'解析完成，可用于问答':'上传完成，正在解析'}</h3>${tag(ready?'已就绪':'解析中',ready?'done':'running')}</div><div class="progress"><span></span></div><p class="tiny">${ready?'服务端就绪状态的本地模拟。':'可以离开本页，稍后在文档列表查看处理状态。'}</p>${btn('查看文档列表','kb','full')}</div>`:btn('确认导入','','primary full','upload-submit')}${parsing?'<button class="democtl" data-act="parse-complete">演示：服务端完成解析</button>':''}`}
function chat(){return `<div class="row between"><span class="tag done">产品与业务资料</span><button class="textbtn" data-act="chat-history">历史会话 ${icon('clock')}</button></div><div class="tiny" style="text-align:center;margin:10px 0 24px">今天 09:12 · 当前空间内的会话</div><div class="msg user"><div class="bubble">产品上线前需要准备哪些资料？</div></div><div class="msg"><div class="who">${icon('spark')}知识问答助手</div><div class="bubble"><div class="tiny" style="color:var(--accent);margin:8px 0 13px">✓ 已检索团队知识 · 3 条相关内容</div><p>建议先准备以下三类资料，让发布更从容：</p><p><b>01 / 产品说明</b><br>明确核心功能、适用用户与使用边界，确保团队对这次发布有共同理解。</p><p><b>02 / 验收清单</b><br>覆盖关键业务路径、权限与异常场景，并标注负责人和当前状态。</p><p><b>03 / 运营材料</b><br>准备帮助文档、常见问题与反馈入口，让用户能够顺利开始使用。</p><button class="citation" data-go="document"><b>[1] 产品上线检查清单</b><div class="tiny">引用片段 · 查看原文与所属知识库 ${icon('chev')}</div></button></div></div>${state.userMessages.map(x=>`<div class="msg user"><div class="bubble">${esc(x)}</div></div>`).join('')}${state.assistantMessage?`<div class="msg"><div class="who">${icon('spark')}知识问答助手</div><div id="stream-answer" class="bubble">${esc(state.assistantMessage)}</div></div>`:''}<div class="row between"><button class="textbtn" data-act="chat-suggestion">继续整理成待办清单</button><button class="textbtn" data-act="chat-stop">停止输出</button></div><p class="tiny">AI 回答需核对引用。当前内容为虚构示例。</p>`}
function states(){let types={empty:['还没有任务','从一个想法开始，选择助手帮你完成第一项工作。','agents','选择助手'],offline:['暂时无法连接','已显示最近一次缓存。恢复后读取同一任务，不会重新发起。','execution','查看原任务'],forbidden:['你没有访问权限','这份资源不在当前账号授权范围内，可联系空间管理员确认。','workspace','查看工作空间'],unavailable:['当前空间尚未开通','后台尚未装配任务能力。你仍可使用已开放的知识问答。','chat','使用知识问答'],expired:['登录已失效','请重新登录。本地未提交内容不会自动变成新任务。','login','重新登录'],syncing:['正在恢复任务','正在读取快照和后续事件，不会重复创建任务或计费。','execution','查看任务']};let e=types[state.errorType]||types.offline;return `${hfHead('异常状态规范','说明发生了什么，也给出正确的下一步。')}<div class="grid2">${Object.entries({empty:'空数据',offline:'断网',forbidden:'无权限',unavailable:'未开通',expired:'登录失效',syncing:'恢复中'}).map(([k,v])=>`<button data-act="error-type" data-value="${k}" class="btn small ${state.errorType===k?'primary':''}">${v}</button>`).join('')}</div><div class="space"></div><div class="card empty">${icon(state.errorType==='forbidden'?'shield':state.errorType==='offline'?'wifi':'tasks')}<h2>${e[0]}</h2><p>${e[1]}</p>${btn(e[3],e[2],'primary')}</div><div class="card"><div class="hf-eyebrow">开发与验收约定</div><p class="muted">错误、无权、未开通和空数据不是同一件事。状态同时有图形与文字，不仅依靠颜色。</p>${hfKv('请求标识','DEMO-TRACE-2401')}${hfKv('缓存时点',state.errorType==='offline'?'09:40（示例）':'不适用')}</div>`}
